 "content": "from collections import Counter

def transform(grid):
    # Keep the background and regularly-shaped colored patches; erase isolated
    # contamination, and repair single-cell defects inside repeated patches.
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    for color in set(v for row in grid for v in row) - {bg}:
        # Candidate fixed rectangles, detected from cells of this color; permit
        # sparse defects but require a substantial density and at least 2x2.
        for r0 in range(h):
            for c0 in range(w):
                if grid[r0][c0] != color:
                    continue
                for r1 in range(r0+1, h):
                    for c1 in range(c0+1, w):
                        area=(r1-r0+1)*(c1-c0+1)
                        if area > 70: break
                        count=sum(grid[r][c] == color for r in range(r0,r1+1) for c in range(c0,c1+1))
                        if count >= max(4, area-2) and count/area >= .8:
                            for r in range(r0,r1+1):
                                for c in range(c0,c1+1): out[r][c]=color
    return out

if __name__ == '__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
